import type { VariableConfig } from '../../Variable'
import type { Record } from '../../../db/Record'
import type { TableName } from '../../../db/Table'

/**
 * Configuration type for reference variables
 */
export type ReferenceVariableType<
    RefTable extends TableName = TableName,
    Type extends Record<RefTable> | Now.Internal.ExplicitKey | string =
        | Record<RefTable>
        | Now.Internal.ExplicitKey
        | string,
> = VariableConfig<Type> & {
    /** Table that is being referenced by this variable */ referenceTable: RefTable
} & {
    /** Type of reference qualifier. Determines which qualifier field to use. */
    useReferenceQualifier?: 'simple' | 'dynamic' | 'advanced'
    /** Filter reference based on a filter condition (use without useReferenceQualifier or with 'simple'). Mutually exclusive with dynamicRefQual and referenceQual. */
    referenceQualCondition?: string
    /** Dynamic reference qualifier (use with useReferenceQualifier='dynamic'). Mutually exclusive with referenceQualCondition and referenceQual. */
    dynamicRefQual?: string | Record<'sys_filter_option_dynamic'>
    /** Advanced reference qualifier (use with useReferenceQualifier='advanced'). Mutually exclusive with referenceQualCondition and dynamicRefQual. */
    referenceQual?: string
}

/**
 * A Variable for a reference field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the reference variable including:
 *   * **question** - Question text displayed to the user
 *   * **referenceTable** - Table that is being referenced by this variable
 *   * **useReferenceQualifier**? - Type of reference qualifier ('simple', 'dynamic', or 'advanced')
 *   * **referenceQualCondition**? - Filter reference based on a filter condition (only with 'simple')
 *   * **dynamicRefQual**? - Filter reference based on a filter condition (only with 'dynamic')
 *   * **referenceQual**? - Advanced reference qualifier (only with 'advanced')
 *   * And all other properties from the base Variable type
 */
export function ReferenceVariable(config: ReferenceVariableType) {
    return config
}
